    for (int iter = 0; iter < max_iter; iter++) {
        double fx = f(x);
        if (fabs(fx) < tol) return x;
        double h = 1e-5;
        double df = (f(x + h) - fx) / h;
        if (fabs(df) < 1e-12) break;
        x = x - fx / df;
    }
    return x;
}

